func TestSnapshotKeepsHealthAndActivityIndependent(t *testing.T) {
	now := time.Date(2026, 10, 13, 20, 0, 0, 0, time.UTC)
	store := cache.New(func() time.Time { return now })
	store.Register("ups-main", "nut", time.Minute)
	store.Register("wago-main", "snmp", time.Minute)
	store.Success("ups-main", []metrics.Metric{{Name: "ups.status", Value: "OL"}}, 10*time.Millisecond)

	hub := New(store, func() time.Time { return now }, 2)
	initial := hub.Snapshot()
	if initial.SchemaVersion != 1 || initial.Service != "running" || initial.Health.Code != 1 || initial.Health.State != "degraded" {
		t.Fatalf("initial status=%+v", initial)
	}
	if initial.Activity.Active || len(initial.Activity.Collectors) != 0 {
		t.Fatalf("initial activity=%+v", initial.Activity)
	}
	if initial.Collectors["ups-main"].Health != "ok" || initial.Collectors["wago-main"].Health != "degraded" {
		t.Fatalf("collector states=%+v", initial.Collectors)
	}

	hub.PollStarted("wago-main")
	active := hub.Snapshot()
	if !active.Activity.Active || len(active.Activity.Collectors) != 1 || active.Activity.Collectors[0] != "wago-main" || !active.Collectors["wago-main"].Polling {
		t.Fatalf("active status=%+v", active)
	}

	store.Failure("wago-main", errors.New("secret detail"), 20*time.Millisecond)
	hub.PollFinished("wago-main")
	failed := hub.Snapshot()
	if failed.Health.Code != 2 || failed.Health.State != "failed" || failed.Activity.Active || failed.Collectors["wago-main"].Health != "failed" {
		t.Fatalf("failed status=%+v", failed)
	}
	if failed.Sequence <= initial.Sequence {
		t.Fatalf("sequence did not advance: initial=%d failed=%d", initial.Sequence, failed.Sequence)
	}
}

func TestActivityTracksOverlappingPolls(t *testing.T) {
	store := cache.New(time.Now)
	hub := New(store, time.Now, 2)
	hub.PollStarted("ups-main")
	hub.PollStarted("wago-main")
	hub.PollStarted("wago-main")

	got := hub.Snapshot()
	if len(got.Activity.Collectors) != 2 || got.Activity.Collectors[0] != "ups-main" || got.Activity.Collectors[1] != "wago-main" {
		t.Fatalf("activity=%+v", got.Activity)
	}
	hub.PollFinished("wago-main")
	if !hub.Snapshot().Collectors["wago-main"].Polling {
		t.Fatal("nested activity ended too early")
	}
	hub.PollFinished("wago-main")
	if hub.Snapshot().Collectors["wago-main"].Polling {
		t.Fatal("activity remained after balanced finishes")
	}
}

func TestSubscriptionsAreBoundedCoalescedAndClosed(t *testing.T) {
	store := cache.New(time.Now)
	hub := New(store, time.Now, 1)
	events, unsubscribe, err := hub.Subscribe()
	if err != nil {
		t.Fatal(err)
	}
	if _, _, err := hub.Subscribe(); !errors.Is(err, ErrTooManySubscribers) {
		t.Fatalf("second subscribe error=%v", err)
	}

	hub.PollStarted("ups-main")
	hub.PollFinished("ups-main")
	select {
	case <-events:
	default:
		t.Fatal("subscriber was not notified")
	}
	select {
	case <-events:
		t.Fatal("notifications were not coalesced")
	default:
	}

	unsubscribe()
	_, replacementUnsubscribe, err := hub.Subscribe()
	if err != nil {
		t.Fatalf("replacement subscribe: %v", err)
	}
	replacementUnsubscribe()

	closedEvents, _, err := hub.Subscribe()
	if err != nil {
		t.Fatal(err)
	}
	hub.Close()
	if _, open := <-closedEvents; open {
		t.Fatal("subscription stayed open after hub close")
	}
	if _, _, err := hub.Subscribe(); !errors.Is(err, ErrClosed) {
		t.Fatalf("subscribe after close error=%v", err)
	}
}

// TestHubNotifiesWhenFreshDataBecomesStale verifies time-derived health transitions are pushed without waiting for a poll to finish.
func TestHubNotifiesWhenFreshDataBecomesStale(t *testing.T) {
	store := cache.New(time.Now)
	store.Register("slow", "snmp", 20*time.Millisecond)
	store.Success("slow", nil, time.Millisecond)
	hub := newHub(store, time.Now, 1, 5*time.Millisecond)
	t.Cleanup(hub.Close)
	initial := hub.Snapshot()
	if initial.Health.Code != 0 {
		t.Fatalf("initial health=%+v", initial.Health)
	}
	changes, unsubscribe, err := hub.Subscribe()
	if err != nil {
		t.Fatal(err)
	}
	defer unsubscribe()

	select {
	case <-changes:
		snapshot := hub.Snapshot()
		if snapshot.Sequence <= initial.Sequence || snapshot.Health.Code != 1 || !snapshot.Collectors["slow"].Stale {
			t.Fatalf("stale snapshot=%+v", snapshot)
		}
	case <-time.After(500 * time.Millisecond):
		t.Fatal("no notification when collector data became stale")
	}
}
